bounded_host_request.command:
set -euo pipefail
name=gace-createvdobot-videobot-poll-1
test "$(docker inspect -f '{{.State.Running}}' "$name" 2>/dev/null)" = true || { echo STK04_DIAG_CONTAINER_NOT_RUNNING; exit 61; }
echo STK04_DIAG_CONTAINER_RUNNING=YES
docker exec -i "$name" node --input-type=module - <<'NODE'
import pg from 'pg';
import {readFileSync} from 'node:fs';
import {createTelegramBotApi} from './src/telegram/botApi.mjs';
import {createCreatorTelegramFetch} from './src/runtime/creatorEgress.mjs';
const env=process.env;
const pool=new pg.Pool({
 host:env.VIDEOBOT_DB_HOST,database:env.VIDEOBOT_DB_NAME,user:env.VIDEOBOT_DB_USER,
 password:readFileSync(env.VIDEOBOT_DB_PASSWORD_FILE,'utf8').trim(),max:1,
 connectionTimeoutMillis:5000});
const egress=createCreatorTelegramFetch(globalThis.fetch);
try {
 const {rows}=await pool.query(
  "SELECT r.phase,r.kind,r.pack_name,r.file_unique_id,s.state->>'screen' AS screen FROM videobot_sticker_registration_receipts r LEFT JOIN videobot_creator_sessions s ON s.owner_user_id=r.owner_user_id WHERE r.phase<>'registered' ORDER BY r.updated_at DESC LIMIT 3");
 console.log('STK04_RECENT_PENDING_COUNT='+rows.length);
 const api=createTelegramBotApi({
  token:readFileSync(env.VIDEOBOT_TELEGRAM_TOKEN_FILE,'utf8').trim(),
  fetchImpl:egress.fetch,timeoutMs:15000});
 let index=0;
 for(const row of rows){
  console.log('STK04_PENDING_'+index+'_PHASE='+row.phase);
  console.log('STK04_PENDING_'+index+'_SCREEN='+(row.screen??'UNKNOWN'));
  if(!row.file_unique_id){console.log('STK04_PENDING_'+index+'_REMOTE=NO_UPLOAD_RECEIPT');index++;continue;}
  try{
   const set=await api('getStickerSet',{name:row.pack_name});
   const found=set?.stickers?.some(s=>s.file_unique_id===row.file_unique_id);
   console.log('STK04_PENDING_'+index+'_REMOTE='+(found?'REGISTERED':'NOT_OBSERVED'));
  }catch{
   console.log('STK04_PENDING_'+index+'_REMOTE=READBACK_FAILED');
  }
  index++;
 }
}catch{
 console.log('STK04_DIAG_QUERY_FAILED');
 process.exitCode=70;
}finally{
 await egress.close();
 await pool.end();
}
NODE
